-- Avengers: Endgame tại HN Phòng 1 (nhiều suất để có nhiều vé) IF NOT EXISTS (SELECT 1 FROM showtimes s JOIN rooms r ON s.room_id = r.room_id JOIN cinemas c ON r.cinema_id = c.cinema_id JOIN movie m ON s.movie_id = m.movie_id WHERE m.title = N'Avengers: Endgame' AND c.name = N'MovieZone Hà Nội' AND r.name = N'Phòng 1' AND s.start_time = '2026-01-15 19:00:00') INSERT INTO showtimes (start_time, surcharge, movie_id, room_id) SELECT '2026-01-15 19:00:00', 0, (SELECT movie_id FROM movie WHERE title = N'Avengers: Endgame'), (SELECT r.room_id FROM rooms r JOIN cinemas c ON r.cinema_id = c.cinema_id WHERE r.name = N'Phòng 1' AND c.name = N'MovieZone Hà Nội');
IF NOT EXISTS (SELECT 1 FROM showtimes s JOIN rooms r ON s.room_id = r.room_id JOIN cinemas c ON r.cinema_id = c.cinema_id JOIN movie m ON s.movie_id = m.movie_id WHERE m.title = N'Avengers: Endgame' AND c.name = N'MovieZone Hà Nội' AND r.name = N'Phòng 1' AND s.start_time = '2026-02-10 20:00:00') INSERT INTO showtimes (start_time, surcharge, movie_id, room_id) SELECT '2026-02-10 20:00:00', 5000, (SELECT movie_id FROM movie WHERE title = N'Avengers: Endgame'), (SELECT r.room_id FROM rooms r JOIN cinemas c ON r.cinema_id = c.cinema_id WHERE r.name = N'Phòng 1' AND c.name = N'MovieZone Hà Nội');
