-- Showtime IDs
DECLARE @st_av1  INT = (SELECT TOP 1 s.showtime_id FROM showtimes s JOIN movie m ON s.movie_id=m.movie_id JOIN rooms r ON s.room_id=r.room_id JOIN cinemas c ON r.cinema_id=c.cinema_id WHERE m.title=N'Avengers: Endgame' AND c.name=N'MovieZone Hà Nội' AND r.name=N'Phòng 1' AND s.start_time='2026-01-15 19:00:00');
DECLARE @st_av2  INT = (SELECT TOP 1 s.showtime_id FROM showtimes s JOIN movie m ON s.movie_id=m.movie_id JOIN rooms r ON s.room_id=r.room_id JOIN cinemas c ON r.cinema_id=c.cinema_id WHERE m.title=N'Avengers: Endgame' AND c.name=N'MovieZone Hà Nội' AND r.name=N'Phòng 1' AND s.start_time='2026-02-10 20:00:00');
