DECLARE @st_in   INT = (SELECT TOP 1 s.showtime_id FROM showtimes s JOIN movie m ON s.movie_id=m.movie_id JOIN rooms r ON s.room_id=r.room_id JOIN cinemas c ON r.cinema_id=c.cinema_id WHERE m.title=N'Interstellar' AND c.name=N'MovieZone Đà Nẵng' AND r.name=N'Phòng 1' AND s.start_time='2026-04-25 19:00:00');
